import sys
from math import isclose

def calculate_area(x1, y1, x2, y2, x3, y3):
    return abs((x1*(y2-y3) + x2*(y3-y1) + x3*(y1-y2)) / 2.0)

def find_intersections(vertices, x):
    intersections = []
    n = len(vertices)
    for i in range(n):
        x1, y1 = vertices[i]
        x2, y2 = vertices[(i + 1) % n]
        if x1 == x2:
            continue
        if min(x1, x2) <= x <= max(x1, x2):
            y = y1 + (y2 - y1) * (x - x1) / (x2 - x1)
            intersections.append(y)
    return sorted(intersections)

def find_bulkhead_placements(C, vertices):
    min_x = min(x for x, y in vertices)
    max_x = max(x for x, y in vertices)

    # Binary search for the maximum number of bulkheads
    left, right = 1, 100
    while left < right:
        mid = (left + right + 1) // 2
        step = (max_x - min_x) / mid
        valid = True
        for i in range(mid):
            x = min_x + (i + 0.5) * step
            intersections = find_intersections(vertices, x)
            if len(intersections) < 2:
                valid = False
                break
            area = 0
            for j in range(len(intersections) - 1):
                area += calculate_area(x, 0, x, intersections[j+1] - intersections[j], x + step, 0)
            if area < C:
                valid = False
                break
        if valid:
            left = mid
        else:
            right = mid - 1

    M = left
    step = (max_x - min_x) / M
    placements = [min_x + (i + 0.5) * step for i in range(M - 1)]

    return M, placements

def main():
    input = sys.stdin.read
    data = input().split()

    C = int(data[0])
    N = int(data[1])
    vertices = [(int(data[i*2+2]), int(data[i*2+3])) for i in range(N)]

    M, placements = find_bulkhead_placements(C, vertices)

    print(M)
    for placement in placements:
        print(f"{placement:.6f}")

if __name__ == "__main__":
    main()
